/// The renderer's fixture suite (T-02 FIX-01 to FIX-05, ADR-0010): template
/// documents, encoded inputs, and pixel expectations at known coordinates.
///
/// Shared by host tests, the device integration test and the dev-only
/// render lab, so every platform runs exactly the same checks. All images
/// are generated by code; no third-party content and no real people.
library;

import 'dart:typed_data';

import '../../../domain/services/composition_renderer.dart';
