import 'fixture_images.dart';
import 'memory_render_source.dart';
import 'png_encoder.dart';
import 'render_checks.dart';

abstract final class FixtureColours {
  static const ivory = Rgb(245, 240, 233);
  static const red = Rgb(200, 40, 40);
  static const green = Rgb(40, 160, 70);
  static const white = Rgb(250, 250, 250);
  static const blue = Rgb(40, 70, 200);
  static const yellow = Rgb(240, 200, 40);
  static const gold = Rgb(232, 180, 60);
  static const pink = Rgb(236, 120, 150);
  static const ink = Rgb(0x33, 0x29, 0x1F);
  static const markerLeft = Rgb(220, 30, 30);
  static const markerRight = Rgb(30, 30, 220);
  static const workspace = Rgb(0x8A, 0x8A, 0x8A);
  static const pageOutline = Rgb(0xE0, 0x21, 0x8A);
  static const black = Rgb(0, 0, 0);
  static const pureWhite = Rgb(255, 255, 255);
  static const pureRed = Rgb(255, 0, 0);
}

ArgbColor _argb(Rgb colour) => ArgbColor(colour.argb);

/// Petal opacity as stored in the flower PNG (8-bit).
const petalAlpha = 191 / 255;

/// A complete render input: a document, the bytes of everything it draws,
/// the photo chosen for each slot, and what the export must look like.
final class RenderFixture {
  RenderFixture({
    required this.id,
    required this.title,
    required this.document,
    required this.assets,
    required this.photos,
    required this.selections,
    this.exportChecks = const [],
  });

  final String id;
  final String title;
  final TemplateDocument document;
  final Map<String, Uint8List> assets;
  final Map<String, Uint8List> photos;
  final Map<int, SlotPhoto> selections;

  /// Pixel checks on the full-resolution export (PNG, unflattened).
  final List<PixelCheck> exportChecks;

  RenderSource get source => MemoryRenderSource(assets: assets, photos: photos);

  TemplateRender get render =>
      TemplateRender(document: document, photos: selections, source: source);

  int get widthPx => document.page.widthPx;
  int get heightPx => document.page.heightPx;
}

/// An encoded image ready for a fixture: bytes, content id and metadata.
final class FixtureImage {
  FixtureImage(RgbaImage image, {this.name})
    : bytes = encodePngRgba(
        width: image.width,
        height: image.height,
        rgba: image.pixels,
      ),
      widthPx = image.width,
      heightPx = image.height;

  final Uint8List bytes;
  final int widthPx;
  final int heightPx;
  final String? name;

  late final String id = assetIdOf(bytes);

  TemplateAsset get asset => TemplateAsset(
    mediaType: AssetMediaType.png,
    byteLength: bytes.length,
    widthPx: widthPx,
    heightPx: heightPx,
    name: name,
  );
}

BackgroundLayer _solidBackground(Rgb colour) => BackgroundLayer(
  id: 'background',
  zIndex: 0,
  fill: SolidFill(_argb(colour)),
);

NormalizedRect _px(
  double x,
  double y,
  double w,
  double h,
  int pageW,
  int pageH,
) => NormalizedRect(
  x: x / pageW,
  y: y / pageH,
  width: w / pageW,
  height: h / pageH,
);

// ------------------------------------------------------------------ FIX-01

/// FIX-01 (4x6 portrait, 1200x1800), in page pixels:
///
/// * slot A (0): 120,108 960x720; photo A 1600x1200 vertical stripes, cover
///   scale 0.6, no crop.
/// * slot B (1): 120,972 960x720, 40 px corners; photo B 1200x1600
///   horizontal stripes, cover scale 0.8, crop rows 350..1250.
/// * flower: 300,600 600x600 (disc radius 90 at 600,900): crosses the bottom
///   edge of slot A, the gap and the top edge of slot B.
/// * marker: 970,810 360x180 turned 90° clockwise about its centre, so it
///   covers x 1060..1240 and overflows the right page edge.
///
/// With [flowerBelowSlots], the flower paints under both slots.
RenderFixture fix01({bool flowerBelowSlots = false}) {
  final photoA = FixtureImage(
    stripes(
      width: 1600,
      height: 1200,
      stripePx: 100,
      vertical: true,
      even: FixtureColours.red,
      odd: FixtureColours.white,
    ),
  );
  final photoB = FixtureImage(
    stripes(
      width: 1200,
      height: 1600,
      stripePx: 100,
      vertical: false,
      even: FixtureColours.blue,
      odd: FixtureColours.yellow,
    ),
  );
  final flowerImage = FixtureImage(flower(size: 800), name: 'flower.png');
  final markerImage = FixtureImage(marker(width: 400, height: 200));
  return RenderFixture(
    id: flowerBelowSlots ? 'FIX-01b' : 'FIX-01',
    title: flowerBelowSlots
        ? '4x6, flower under both slots'
        : '4x6, flower across both slots',
    document: TemplateDocument(
      page: PageSpec.fourBySixPortrait,
      assets: {
        flowerImage.id: flowerImage.asset,
        markerImage.id: markerImage.asset,
      },
      layers: [
        _solidBackground(FixtureColours.ivory),
        const PhotoSlotLayer(
          id: 'slot-a',
          zIndex: 10,
          slotIndex: 0,
          frame: NormalizedRect(x: 0.1, y: 0.06, width: 0.8, height: 0.4),
        ),
        const PhotoSlotLayer(
          id: 'slot-b',
          zIndex: 11,
          slotIndex: 1,
          frame: NormalizedRect(x: 0.1, y: 0.54, width: 0.8, height: 0.4),
          clip: RoundedRectClip(40 / 720),
        ),
        ImageLayer(
          id: 'flower',
          zIndex: flowerBelowSlots ? 5 : 20,
          assetId: flowerImage.id,
          frame: _px(300, 600, 600, 600, 1200, 1800),
        ),
        ImageLayer(
          id: 'marker',
          zIndex: 30,
          assetId: markerImage.id,
          frame: _px(970, 810, 360, 180, 1200, 1800),
          rotationDegrees: 90,
        ),
      ],
    ),
    assets: {
      flowerImage.id: flowerImage.bytes,
      markerImage.id: markerImage.bytes,
    },
    photos: {'photo-a': photoA.bytes, 'photo-b': photoB.bytes},
    selections: const {0: SlotPhoto('photo-a'), 1: SlotPhoto('photo-b')},
    exportChecks: flowerBelowSlots ? _fix01BelowChecks : _fix01Checks,
  );
}

