/// FIX-02 (2x6 strip, 600x1800): three slots (36,54 / 36,558 / 36,1062, each
/// 528x468) with solid red, green and blue photos, a centred title in the
/// bottom band (36..564 x 1548..1746) and a 3 pt frame along the page edge,
/// drawn inside it (12.5 px) and above everything.
RenderFixture fix02() {
  final photos = {
    'red': FixtureImage(
      solid(width: 640, height: 480, colour: FixtureColours.red),
    ),
    'green': FixtureImage(
      solid(width: 640, height: 480, colour: FixtureColours.green),
    ),
    'blue': FixtureImage(
      solid(width: 640, height: 480, colour: FixtureColours.blue),
    ),
  };
  PhotoSlotLayer slot(int index, double top) => PhotoSlotLayer(
    id: 'slot-$index',
    zIndex: 10 + index,
    slotIndex: index,
    frame: _px(36, top, 528, 468, 600, 1800),
  );
  return RenderFixture(
    id: 'FIX-02',
    title: '2x6 strip: three slots, centred text, frame',
    document: TemplateDocument(
      page: PageSpec.twoBySix,
      layers: [
        _solidBackground(FixtureColours.ivory),
        slot(0, 54),
        slot(1, 558),
        slot(2, 1062),
        TextLayer(
          id: 'title',
          zIndex: 40,
          frame: fix02TitleFrame,
          text: 'Porcelain',
          font: const BundledFont(
            BundledFontFamily.cormorantGaramond,
            weight: 600,
          ),
          sizePt: 28,
          color: _argb(FixtureColours.ink),
        ),
        ShapeLayer(
          id: 'frame',
          zIndex: 50,
          frame: NormalizedRect.page,
          shape: ShapeKind.rect,
          stroke: Stroke(widthPt: 3, color: _argb(FixtureColours.ink)),
        ),
      ],
    ),
    assets: const {},
    photos: {
      for (final MapEntry(:key, :value) in photos.entries) key: value.bytes,
    },
    selections: const {
      0: SlotPhoto('red'),
      1: SlotPhoto('green'),
      2: SlotPhoto('blue'),
    },
    exportChecks: const [
      PixelCheck('photo 1 fills slot 1', 300, 288, FixtureColours.red),
      PixelCheck('photo 2 fills slot 2', 300, 792, FixtureColours.green),
      PixelCheck('photo 3 fills slot 3', 300, 1296, FixtureColours.blue),
      PixelCheck('gap between slots 1 and 2', 300, 540, FixtureColours.ivory),
