// ------------------------------------------------------------------ FIX-04

/// FIX-04 halo probe (600x600): a scaled, rotated disc whose hidden
/// transparent colour contrasts with both the disc and the page. Every
/// output pixel must stay the page colour.
({RenderFixture fixture, Rgb expected}) fix04Halo({
  required bool whiteOnWhite,
}) {
  final colour = whiteOnWhite ? FixtureColours.pureWhite : FixtureColours.black;
  final hidden = whiteOnWhite ? FixtureColours.black : FixtureColours.pureWhite;
  final disc = FixtureImage(
    haloDisc(size: 500, colour: colour, transparentRgb: hidden),
  );
  return (
    fixture: RenderFixture(
      id: whiteOnWhite ? 'FIX-04w' : 'FIX-04k',
      title: whiteOnWhite ? 'halo: white on white' : 'halo: black on black',
      document: TemplateDocument(
        page: const PageSpec(
          width: 2,
          height: 2,
          unit: LengthUnit.inch,
          dpi: 300,
        ),
        assets: {disc.id: disc.asset},
        layers: [
          _solidBackground(colour),
          ImageLayer(
            id: 'disc',
            zIndex: 1,
            assetId: disc.id,
            frame: const NormalizedRect(
              x: 0.12,
              y: 0.15,
              width: 0.61,
              height: 0.61,
            ),
            rotationDegrees: 17,
          ),
        ],
      ),
      assets: {disc.id: disc.bytes},
      photos: const {},
      selections: const {},
    ),
    expected: colour,
  );
}

