// ----------------------------------------------------------- clip and fit

/// Clip shapes, fits, mirroring, borders, group opacity and hidden layers
/// on a 4x4 page (1200x1200), each slot 480x480:
///
/// * slot 0 at 60,60: ellipse, solid red photo.
/// * slot 1 at 660,60: ring mask (radii 72 and 216 about 900,300), green.
/// * slot 2 at 60,660: contain-fit 2:1 blue photo (480x240 at y 780..1020),
///   rounded corners and a 4 pt gold border inside the edge.
/// * slot 3 at 660,660: quadrant photo, mirrored as guests see it.
/// * a 96 px square at 552,552: red fill, 6 pt black line, opacity 0.5 as a
///   group, so the line never shows the fill through it.
/// * a hidden black square over the top-left corner.
RenderFixture clipAndFit() {
  final mask = FixtureImage(ringMask(size: 200), name: 'ring.png');
  return RenderFixture(
    id: 'CLIP',
    title: '4x4: clip shapes, mask, fits, mirroring, group opacity',
    document: TemplateDocument(
      page: PageSpec.fourByFour,
      assets: {mask.id: mask.asset},
      layers: [
        _solidBackground(FixtureColours.ivory),
        PhotoSlotLayer(
          id: 'ellipse',
          zIndex: 10,
          slotIndex: 0,
          frame: _px(60, 60, 480, 480, 1200, 1200),
          clip: const EllipseClip(),
        ),
        PhotoSlotLayer(
          id: 'ring',
          zIndex: 11,
          slotIndex: 1,
          frame: _px(660, 60, 480, 480, 1200, 1200),
          clip: MaskClip(mask.id),
        ),
        PhotoSlotLayer(
          id: 'contain',
          zIndex: 12,
          slotIndex: 2,
          frame: _px(60, 660, 480, 480, 1200, 1200),
          fit: PhotoFit.contain,
          clip: const RoundedRectClip(0.1),
          border: Stroke(widthPt: 4, color: _argb(FixtureColours.gold)),
        ),
        PhotoSlotLayer(
          id: 'mirrored',
          zIndex: 13,
          slotIndex: 3,
          frame: _px(660, 660, 480, 480, 1200, 1200),
        ),
        ShapeLayer(
          id: 'translucent',
          zIndex: 20,
          frame: _px(552, 552, 96, 96, 1200, 1200),
          shape: ShapeKind.rect,
          fill: _argb(FixtureColours.pureRed),
          stroke: Stroke(widthPt: 6, color: _argb(FixtureColours.black)),
          opacity: 0.5,
        ),
        ShapeLayer(
          id: 'hidden',
          zIndex: 30,
          frame: _px(0, 0, 60, 60, 1200, 1200),
          shape: ShapeKind.rect,
          fill: _argb(FixtureColours.black),
          visible: false,
        ),
      ],
    ),
    assets: {mask.id: mask.bytes},
    photos: {
      'red': FixtureImage(
        solid(width: 400, height: 400, colour: FixtureColours.red),
      ).bytes,
      'green': FixtureImage(
        solid(width: 400, height: 400, colour: FixtureColours.green),
      ).bytes,
      'blue': FixtureImage(
        solid(width: 800, height: 400, colour: FixtureColours.blue),
      ).bytes,
      'quadrants': FixtureImage(quadrants(width: 400, height: 400)).bytes,
    },
    selections: const {
      0: SlotPhoto('red'),
      1: SlotPhoto('green'),
      2: SlotPhoto('blue'),
      3: SlotPhoto('quadrants', mirrored: true),
    },
    exportChecks: [
      const PixelCheck(
        'ellipse centre shows the photo',
        300,
        300,
        FixtureColours.red,
      ),
      const PixelCheck(
        'ellipse, just inside its top',
