/// A top-to-bottom gradient from white to black (2x2 in, 600x600).
RenderFixture gradientBackground() => RenderFixture(
  id: 'GRADIENT',
  title: 'Gradient background',
  document: TemplateDocument(
    page: const PageSpec(width: 2, height: 2, unit: LengthUnit.inch, dpi: 300),
    layers: [
      BackgroundLayer(
        id: 'background',
        zIndex: 0,
        fill: LinearGradientFill(
          angleDegrees: 90,
          stops: [
            GradientStop(0, _argb(FixtureColours.pureWhite)),
            GradientStop(1, _argb(FixtureColours.black)),
          ],
        ),
      ),
    ],
  ),
  assets: const {},
  photos: const {},
  selections: const {},
  exportChecks: const [
    PixelCheck('top is white', 300, 1, FixtureColours.pureWhite),
    PixelCheck('middle is mid grey', 300, 300, Rgb(127, 127, 127)),
    PixelCheck('bottom is black', 300, 598, FixtureColours.black),
    PixelCheck(
      'the gradient runs top to bottom only',
      5,
      300,
      Rgb(127, 127, 127),
    ),
  ],
);

// ---------------------------------------------------------------- alpha

/// A flower on a page with no background (600x600): PNG keeps the
/// transparency; JPEG flattens it onto the output colour (AC-0406).
RenderFixture transparentPage() {
  final flowerImage = FixtureImage(flower(size: 800), name: 'flower.png');
  return RenderFixture(
    id: 'ALPHA',
    title: 'Transparent page with a translucent flower',
    document: TemplateDocument(
      page: const PageSpec(
        width: 2,
        height: 2,
        unit: LengthUnit.inch,
        dpi: 300,
      ),
      assets: {flowerImage.id: flowerImage.asset},
      layers: [
        ImageLayer(
          id: 'flower',
          zIndex: 1,
          assetId: flowerImage.id,
          frame: const NormalizedRect(x: 0.1, y: 0.1, width: 0.8, height: 0.8),
        ),
      ],
    ),
    assets: {flowerImage.id: flowerImage.bytes},
    photos: const {},
    selections: const {},
  );
}

